231	                                occ("G1", key("SEC"), iso(8), iso(9)))))
232	                .andExpect(status().isConflict());
233	
234	        // 已取消不可修改
235	        String cancelled = key("SCH");
236	        String section = key("SEC");
237	        createPlan(cancelled, occ("G1", section, iso(8), iso(9)));
238	        publishPlan(cancelled, key("REQ"));
239	        cancelPlan(cancelled, key("REQ"));
240	        mvc.perform(put("/api/v1/plans/{key}/occupancies", cancelled)
241	                        .contentType(MediaType.APPLICATION_JSON)
242	                        .content(updateBody(key("REQ"), 1, occ("G1", section, iso(8), iso(9)))))
243	                .andExpect(status().isConflict());
244	    }
