package com.example.starter.plan;

import static org.assertj.core.api.Assertions.assertThat;

import com.example.starter.plan.service.PlanService;
import com.example.starter.plan.web.ApiException;
import com.example.starter.plan.web.dto.CreatePlanRequest;
import com.example.starter.plan.web.dto.OccupancyRequest;
import com.example.starter.plan.web.dto.PlanResponse;
import com.example.starter.plan.web.dto.PublishedSlotView;
import com.example.starter.plan.web.dto.UpdateOccupanciesRequest;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 并发与幂等竞态测试：并发发布互斥、同键并发创建、更新与发布按提交顺序生效、
 * 取消不误释放其他计划时隙。
 */
@SpringBootTest
class PlanConcurrencyTest {

    private static final ZoneId SH = ZoneId.of("Asia/Shanghai");
    private static final LocalDate DAY = LocalDate.of(2026, 9, 22);

    @Autowired
    private PlanService service;

    @Autowired
    private JdbcTemplate jdbc;

    @Test
    void concurrentPublishSameSectionOnlyOneSucceeds() throws Exception {
        String section = key("SEC");
        int contenders = 4;
        List<String> scheduleKeys = new ArrayList<>();
        for (int i = 0; i < contenders; i++) {
            String scheduleKey = key("SCH");
            createDraft(scheduleKey, section, 8, 9);
            scheduleKeys.add(scheduleKey);
        }

        List<Outcome> outcomes = runConcurrently(scheduleKeys.stream()
                .<Callable<Outcome>>map(sk -> () -> {
                    try {
                        service.publish(sk, key("REQ"));
                        return Outcome.OK;
                    } catch (ApiException e) {
                        assertThat(e.status()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
                        return Outcome.CONFLICT;
                    }
                }).toList());

        assertThat(outcomes.stream().filter(o -> o == Outcome.OK).count()).isEqualTo(1);
        assertThat(outcomes.stream().filter(o -> o == Outcome.CONFLICT).count())
                .isEqualTo(contenders - 1);

        // 最终该区段只有一张计划的时隙生效
        List<PublishedSlotView> slots = service.getPublishedSlots(DAY, section);
        assertThat(slots).hasSize(1);
    }

    @Test
    void concurrentCreateSameKeyReturnsFirstResult() throws Exception {
        String scheduleKey = key("SCH");
        String requestKey = key("REQ");
        String section = key("SEC");
        int threads = 4;

        List<OccupancyRequest> occupancies = List.of(occ(section, 8, 9));
        List<Callable<PlanResponse>> tasks = new ArrayList<>();
        for (int i = 0; i < threads; i++) {
            tasks.add(() -> service.createDraft(new CreatePlanRequest(
                    requestKey, scheduleKey, DAY, occupancies)));
        }
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch ready = new CountDownLatch(threads);
        CountDownLatch go = new CountDownLatch(1);
        List<Future<PlanResponse>> futures = tasks.stream()
                .map(t -> pool.submit(() -> {
                    ready.countDown();
                    go.await();
                    return t.call();
                })).toList();
        ready.await();
        go.countDown();
        List<PlanResponse> responses = new ArrayList<>();
        for (Future<PlanResponse> f : futures) {
            responses.add(f.get(30, TimeUnit.SECONDS));
        }
        pool.shutdown();

        // 全部返回首次结果，且库里只有一张计划
        assertThat(responses).allMatch(r -> r.equals(responses.get(0)));
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM rail_day_plan WHERE schedule_key = ?",
                Integer.class, scheduleKey);
        assertThat(count).isEqualTo(1);
    }

    @Test
    void concurrentUpdateAndPublishApplyInCommitOrder() throws Exception {
        String section = key("SEC");
        String scheduleKey = key("SCH");
        createDraft(scheduleKey, section, 8, 9);

        List<Outcome> outcomes = runConcurrently(List.of(
                () -> {
                    try {
                        service.replaceOccupancies(scheduleKey, new UpdateOccupanciesRequest(
                                key("REQ"), 1, List.of(occ(section, 10, 11))));
                        return Outcome.OK;
                    } catch (ApiException e) {
                        // 发布先提交时更新应得 409 状态冲突
                        assertThat(e.status()).isEqualTo(HttpStatus.CONFLICT);
                        return Outcome.CONFLICT;
                    }
                },
                () -> {
                    service.publish(scheduleKey, key("REQ"));
                    return Outcome.OK;
                }));

        // 发布必须成功；更新要么先于发布成功（版本 2），要么因已发布而 409（版本 1）
        PlanResponse plan = service.getPlan(scheduleKey);
        assertThat(plan.status()).isEqualTo("PUBLISHED");
        if (outcomes.get(0) == Outcome.OK) {
            assertThat(plan.version()).isEqualTo(2);
            assertThat(plan.occupancies().get(0).startUtc()).isEqualTo(at(10));
        } else {
            assertThat(plan.version()).isEqualTo(1);
            assertThat(plan.occupancies().get(0).startUtc()).isEqualTo(at(8));
        }
    }

    @Test
    void cancelDoesNotReleaseOtherPlansSlots() {
        String section = key("SEC");
        String planA = key("SCH");
        String planB = key("SCH");
        createDraft(planA, section, 8, 9);
        createDraft(planB, section, 9, 10);
        service.publish(planA, key("REQ"));
        service.publish(planB, key("REQ"));

        service.cancel(planA, key("REQ"));

        // A 的时隙释放：新计划可占用 08:00-09:00
        String intoA = key("SCH");
        createDraft(intoA, section, 8, 9);
        service.publish(intoA, key("REQ"));

        // B 的时隙不受影响：09:30-10:30 与 B 冲突，必须 422
        String intoB = key("SCH");
        createDraft(intoB, section, 9, 10);
        try {
            service.publish(intoB, key("REQ"));
            org.assertj.core.api.Assertions.fail("应抛出 422 时隙冲突");
        } catch (ApiException e) {
            assertThat(e.status()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
            assertThat(e.code()).isEqualTo("SLOT_CONFLICT");
        }
        assertThat(service.getPlan(intoB).status()).isEqualTo("DRAFT");
    }

    // ---------- 辅助 ----------

    private enum Outcome {
        OK,
        CONFLICT
    }

    private void createDraft(String scheduleKey, String section, int startHour, int endHour) {
        service.createDraft(new CreatePlanRequest(key("REQ"), scheduleKey, DAY,
                List.of(occ(section, startHour, endHour))));
    }

    private List<Outcome> runConcurrently(List<Callable<Outcome>> tasks) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(tasks.size());
        CountDownLatch ready = new CountDownLatch(tasks.size());
        CountDownLatch go = new CountDownLatch(1);
        List<Future<Outcome>> futures = tasks.stream()
                .map(t -> pool.submit(() -> {
                    ready.countDown();
                    go.await();
                    return t.call();
                })).toList();
        ready.await();
        go.countDown();
        List<Outcome> outcomes = new ArrayList<>();
        for (Future<Outcome> f : futures) {
            outcomes.add(f.get(30, TimeUnit.SECONDS));
        }
        pool.shutdown();
        return outcomes;
    }

    private static OccupancyRequest occ(String section, int startHour, int endHour) {
        return new OccupancyRequest("G-" + UUID.randomUUID(), section,
                at(startHour), at(endHour));
    }

    private static Instant at(int hour) {
        return DAY.atTime(hour, 0).atZone(SH).toInstant();
    }

    private static String key(String prefix) {
        return prefix + "-" + UUID.randomUUID();
    }
}

package com.example.starter.plan;

import static org.assertj.core.api.Assertions.assertThat;

import com.example.starter.plan.service.PlanService;
import com.example.starter.plan.web.ApiException;
import com.example.starter.plan.web.dto.CreatePlanRequest;
import com.example.starter.plan.web.dto.OccupancyRequest;
import com.example.starter.plan.web.dto.RescheduleChainResponse;
import com.example.starter.plan.web.dto.RescheduleRequest;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 改签并发裁决测试：同一旧计划的并发改签最多一次成功；
 * 改签与第三方发布竞争同一时隙时按事务提交顺序裁决，第三方抢不到改签后已占用的时隙。
 */
@SpringBootTest
class PlanRescheduleConcurrencyTest {

    private static final ZoneId SH = ZoneId.of("Asia/Shanghai");
    private static final LocalDate DAY = LocalDate.of(2026, 9, 22);

    @Autowired
    private PlanService service;

    @Autowired
    private JdbcTemplate jdbc;

    @Test
    void concurrentRescheduleSameOldPlanOnlyOneSucceeds() throws Exception {
        String section = key("SEC");
        String oldKey = key("SCH");
        createDraft(oldKey, section, 8, 9);
        service.publish(oldKey, key("REQ"));
        String newA = key("SCH");
        String newB = key("SCH");
        createDraft(newA, section, 9, 10);
        createDraft(newB, section, 9, 10);

        List<Outcome> outcomes = runConcurrently(List.of(
                () -> {
                    try {
                        service.reschedule(oldKey, new RescheduleRequest(key("REQ"), newA, 1, 1));
                        return Outcome.OK;
                    } catch (ApiException e) {
                        assertThat(e.status()).isEqualTo(HttpStatus.CONFLICT);
                        return Outcome.CONFLICT;
                    }
                },
                () -> {
                    try {
                        service.reschedule(oldKey, new RescheduleRequest(key("REQ"), newB, 1, 1));
                        return Outcome.OK;
                    } catch (ApiException e) {
                        assertThat(e.status()).isEqualTo(HttpStatus.CONFLICT);
                        return Outcome.CONFLICT;
                    }
                }));

        // 同一旧计划的两次改签最多一次成功
        assertThat(outcomes.stream().filter(o -> o == Outcome.OK).count()).isEqualTo(1);
        assertThat(outcomes.stream().filter(o -> o == Outcome.CONFLICT).count()).isEqualTo(1);

        // 旧计划只取消一次，恰好一个后继发布、另一个仍为草稿，关联仅一条
        assertThat(service.getPlan(oldKey).status()).isEqualTo("CANCELLED");
        String statusA = service.getPlan(newA).status();
        String statusB = service.getPlan(newB).status();
        assertThat(List.of(statusA, statusB)).containsExactlyInAnyOrder("PUBLISHED", "DRAFT");
        Integer linkCount = jdbc.queryForObject(
                "SELECT COUNT(*) FROM rail_plan_reschedule_link l"
                        + " JOIN rail_day_plan p ON p.id = l.predecessor_plan_id"
                        + " WHERE p.schedule_key = ?",
                Integer.class, oldKey);
        assertThat(linkCount).isEqualTo(1);

        // 链完整有序且长度为 2
        RescheduleChainResponse chain = service.getRescheduleChain(oldKey);
        assertThat(chain.chain()).hasSize(2);
        assertThat(chain.chain().get(0).scheduleKey()).isEqualTo(oldKey);
        assertThat(chain.chain().get(0).status()).isEqualTo("CANCELLED");
        assertThat(chain.chain().get(1).status()).isEqualTo("PUBLISHED");
    }

    @Test
    void concurrentRescheduleAndThirdPartyPublishRaceForSlot() throws Exception {
        String section = key("SEC");
        String oldKey = key("SCH");
        createDraft(oldKey, section, 8, 9);
        service.publish(oldKey, key("REQ"));
        // 改签新草稿与第三方草稿争夺同一时隙 10:00-11:00
        String newKey = key("SCH");
        String thirdParty = key("SCH");
        createDraft(newKey, section, 10, 11);
        createDraft(thirdParty, section, 10, 11);

        List<Outcome> outcomes = runConcurrently(List.of(
                () -> {
                    try {
                        service.reschedule(oldKey, new RescheduleRequest(key("REQ"), newKey, 1, 1));
                        return Outcome.OK;
                    } catch (ApiException e) {
                        assertThat(e.status()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
                        return Outcome.CONFLICT;
                    }
                },
                () -> {
                    try {
                        service.publish(thirdParty, key("REQ"));
                        return Outcome.OK;
                    } catch (ApiException e) {
                        assertThat(e.status()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
                        return Outcome.CONFLICT;
                    }
                }));

        // 恰好一方成功：第三方抢不到改签后已占用的时隙，反之改签整体回滚
        assertThat(outcomes.stream().filter(o -> o == Outcome.OK).count()).isEqualTo(1);
        String newStatus = service.getPlan(newKey).status();
        String thirdStatus = service.getPlan(thirdParty).status();
        if (outcomes.get(0) == Outcome.OK) {
            // 改签胜出：旧取消、新发布、第三方仍草稿
            assertThat(service.getPlan(oldKey).status()).isEqualTo("CANCELLED");
            assertThat(newStatus).isEqualTo("PUBLISHED");
            assertThat(thirdStatus).isEqualTo("DRAFT");
            assertThat(service.getRescheduleChain(oldKey).chain()).hasSize(2);
        } else {
            // 第三方先发布：改签 422 回滚，旧计划仍发布、新草稿仍草稿、无关联
            assertThat(service.getPlan(oldKey).status()).isEqualTo("PUBLISHED");
            assertThat(newStatus).isEqualTo("DRAFT");
            assertThat(thirdStatus).isEqualTo("PUBLISHED");
            assertThat(service.getRescheduleChain(oldKey).chain()).hasSize(1);
        }

        // 最终该区段 10:00-11:00 只有一张计划的时隙生效
        assertThat(service.getPublishedSlots(DAY, section)
                .stream().filter(s -> s.startUtc().equals(at(10))).count())
                .isEqualTo(1);
    }

    // ---------- 辅助 ----------

    private enum Outcome {
        OK,
        CONFLICT
    }

    private void createDraft(String scheduleKey, String section, int startHour, int endHour) {
        service.createDraft(new CreatePlanRequest(key("REQ"), scheduleKey, DAY,
                List.of(new OccupancyRequest("G-" + UUID.randomUUID(), section,
                        at(startHour), at(endHour)))));
    }

    private List<Outcome> runConcurrently(List<Callable<Outcome>> tasks) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(tasks.size());
        CountDownLatch ready = new CountDownLatch(tasks.size());
        CountDownLatch go = new CountDownLatch(1);
        List<Future<Outcome>> futures = tasks.stream()
                .map(t -> pool.submit(() -> {
                    ready.countDown();
                    go.await();
                    return t.call();
                })).toList();
        ready.await();
        go.countDown();
        List<Outcome> outcomes = new ArrayList<>();
        for (Future<Outcome> f : futures) {
            outcomes.add(f.get(30, TimeUnit.SECONDS));
        }
        pool.shutdown();
        return outcomes;
    }

    private static Instant at(int hour) {
        return DAY.atTime(hour, 0).atZone(SH).toInstant();
    }

    private static String key(String prefix) {
        return prefix + "-" + UUID.randomUUID();
    }
}

